async (page) => {
  const br = page.context().browser();
  const res = {};
  const ctxA = await br.newContext({viewport:{width:1920,height:1080},locale:'en-US'});
  const pc = await ctxA.newPage();
  await pc.goto('http://10.17.1.66:3001/en', {waitUntil:'domcontentloaded'});
  await pc.waitForTimeout(7000);
  await pc.locator('button.cinematic-model').first().click();
  await pc.waitForTimeout(1800);
  res.pcMenu = await pc.evaluate(() => {
    const names = ['Nano Banana','Seedream','Pokecut Pro'];
    const cands = Array.from(document.querySelectorAll('div,ul')).filter(d => { const s=(d.innerText||'').trim(); return s.length>10 && s.length<700 && names.every(n=>s.includes(n)); });
    const el = cands[cands.length-1];
    return el ? {cls: String(el.className).slice(0,110), items: el.querySelectorAll('button,li,[class*=item]').length, text: el.innerText.trim().slice(0,240).replace(/\n+/g,' | ')} : null;
  });
  await pc.screenshot({path:'artifacts/2026-09-14_stable_regression_all_archived/evidence/mcp_drift_20260914/pc_model_menu_open.png'});
  await ctxA.close();
  const ctxB = await br.newContext({viewport:{width:390,height:844},isMobile:true,hasTouch:true,deviceScaleFactor:3,locale:'en-US',userAgent:'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1'});
  const mp = await ctxB.newPage();
  await mp.goto('http://10.17.1.66:3001/en', {waitUntil:'domcontentloaded'});
  await mp.waitForTimeout(8000);
  res.mobileFileInput = await mp.evaluate(() => {
    const inp = document.querySelector('input[type=file]');
    if (!inp) return null;
    const chain = [];
    let el = inp;
    for (let i = 0; i < 6 && el; i++) { el = el.parentElement; if (el) chain.push(el.tagName + '|' + String(el.className).slice(0,60) + '|' + (el.innerText||'').trim().slice(0,50).replace(/\n+/g,' / ')); }
    return chain;
  });
  res.mobileTemplateCards = await mp.evaluate(() => {
    const sec = Array.from(document.querySelectorAll('section,div')).find(d => (d.innerText||'').startsWith('Create Faster with'));
    if (!sec) return [];
    return Array.from(sec.querySelectorAll('img[alt]')).map(i => i.getAttribute('alt')).filter(Boolean).slice(0, 24);
  });
  await ctxB.close();
  return JSON.stringify(res);
}
